const items = [
  ...movies.slice(0, 80),
  ...music.slice(0, 55),
  ...tv.slice(0, 40),
  ...events.slice(0, 45),
  ...java.slice(0, 28),
  ...spring.slice(0, 25),
  ...react.slice(0, 26),
  ...nextjs.slice(0, 26),
  ...nest.slice(0, 25),
]

const fail = (message) => {
  console.error(message)
  process.exit(1)
}

if (items.length !== 350) {
  fail(
    `Expected 350 questions, found ${items.length} (movies=${movies.length} music=${music.length} tv=${tv.length} events=${events.length} java=${java.length} spring=${spring.length} react=${react.length} next=${nextjs.length} nest=${nest.length})`,
  )
}

const texts = new Set()
for (const [index, row] of items.entries()) {
  if (row.length !== 5) {
    fail(`Row ${index} does not have 5 columns`)
  }
  const [text, ...answers] = row
  if (texts.has(text)) {
    fail(`Duplicate question text at ${index}: ${text}`)
  }
  texts.add(text)
  if (answers.some((answer) => !answer || !answer.trim())) {
    fail(`Blank answer at ${index}`)
  }
  if (new Set(answers).size !== answers.length) {
    fail(`Duplicate answers at ${index}: ${text}`)
  }
}

const questions = items.map(([text, ...answers]) => ({
  text,
  answers,
  lastUsedDate: NEVER_USED_DATE,
  status: ACTIVE_STATUS,
  submittedBy: SUBMITTED_BY,
  dateSubmitted: DATE_SUBMITTED,
}))

mkdirSync(dirname(OUT), { recursive: true })
writeFileSync(OUT, `${JSON.stringify(questions, null, 2)}\n`)
console.log(`Wrote ${questions.length} questions to ${OUT}`)
